test('legacy-shape-in-use: the retired servedBy alias is reported, the current one is not', () => {
  assert.equal(run({ packs: [], servedBy: { mechanism: 'updates' } }).length, 1);
  assert.deepEqual(run({ packs: [], servedBy: { mechanism: 'versioned' } }), []);
});

